std::unordered_map<int, int> map = {{1, 10}, {2, 20}};

auto it = map.find(1);

// Iterators are invalidated ONLY when a rehash occurs.
// 1. Implicit Rehash (Load Factor exceeded)
map.max_load_factor(0.5f);
map.insert({3, 30}); // May trigger rehash if size exceeds bucket count

// 2. Explicit Rehash (Guaranteed Invalidation)
map.rehash(100);

// State: 'it' is now invalid (UB if accessed).
// Pointers/references to elements are also invalidated.

// Exception: std::unordered_set iterators are stable upon erase.
